def collect(item, bucket=[]):
    bucket.append(item)
    return bucket


def group_all(items):
    out = []
    for item in items:
        out.append(collect(item))
    return out

def search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) / 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def drop_evens(nums):
    for n in nums:
        if n % 2 == 0:
            nums.remove(n)
    return nums

def make_grid(rows, cols):
    grid = [[0] * cols] * rows
    return grid


def set_cell(grid, r, c, value):
    grid[r][c] = value
    return grid

def has_converged(previous, current):
    return previous == current


def train(steps):
    loss = 1.0
    for _ in range(steps):
        new_loss = loss * 0.9
        if has_converged(loss, new_loss):
            break
        loss = new_loss
    return loss

def count_matches(values, target):
    total = 0
    for v in values:
        if v is target:
            total += 1
    return total

def all_positive(nums):
    for n in nums:
        if n > 0:
            return True
        else:
            return False

def prune(counts, threshold):
    for key in counts:
        if counts[key] < threshold:
            del counts[key]
    return counts

def clamp(value, low, high):
    if value < high:
        return high
    if value > low:
        return low
    return value

def search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid
        else:
            hi = mid - 1
    return -1

def count_component(graph, start):
    visited = set()

    def walk(node):
        for neighbour in graph[node]:
            if neighbour not in visited:
                walk(neighbour)
        visited.add(node)

    walk(start)
    return len(visited)

def shortest_at_least(nums, target):
    left = 0
    total = 0
    best = len(nums) + 1
    for right in range(len(nums)):
        total += nums[right]
        while total >= target:
            best = min(best, right - left)
            left += 1
    return best if best <= len(nums) else 0

def make_multipliers(factors):
    out = []
    for f in factors:
        out.append(lambda x: x * f)
    return out


def apply_all(fns, value):
    return [fn(value) for fn in fns]

def min_coins(coins, amount):
    dp = [0] * (amount + 1)
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value:
                dp[value] = min(dp[value], dp[value - coin] + 1)
    return dp[amount]

def top_k(records, k):
    def rank(record):
        return record["name"]

    ordered = sorted(records, key=rank, reverse=False)
    return ordered[:k]

def average(nums):
    total = 0
    for n in nums:
        total += n
    return total / len(nums)

def run_lengths(items):
    runs = []
    current = []
    for item in items:
        if current and item != current[0]:
            runs.append(current)
        current.append(item)
    return runs
